func sessionInfoRefreshURL(view SessionInformationView) string {
	url := "/game-requests/" + view.RequestID + "/session-information"
	if view.Form == nil {
		return url
	}
	if view.Form.Mode == "add" {
		return url + "?session_add=1"
	}
	if view.Form.Mode == "edit" {
		return url + "?session_edit=" + view.Form.EntryID
	}
	return url
}

func sessionFormAction(view SessionInformationView) string {
	if view.Form != nil && view.Form.Mode == "edit" {
		return "/game-requests/" + view.RequestID + "/session-information/" + view.Form.EntryID
	}
	return "/game-requests/" + view.RequestID + "/session-information"
}
func sessionInformationInvalid(errorField, field string) string {
	if errorField == field {
		return "true"
	}
	return "false"
}
func sessionValueInputType(form *SessionInformationForm) string {
	if form != nil && form.IsSecret {
		return "password"
	}
	return "text"
}

